adcs_quat_t q_est, q_tgt, q_conj, q_err;
adcs_vec3_t vec;
double s, angle;

if ((estimated == NULL) || (target == NULL) || (error == NULL)) {
    return ADCS_E_NULL;
}

if ((!isfinite(estimated->w)) || (!isfinite(estimated->x)) ||
    (!isfinite(estimated->y)) || (!isfinite(estimated->z)) ||
    (!isfinite(target->w)) || (!isfinite(target->x)) ||
    (!isfinite(target->y)) || (!isfinite(target->z))) {
    *error = (adcs_vec3_t){0.0, 0.0, 0.0};
    return ADCS_E_NOT_FINITE;
}

if (adcs_quat_normalize(estimated, &q_est) != ADCS_OK) {
    *error = (adcs_vec3_t){0.0, 0.0, 0.0};
    return ADCS_E_DEGENERATE;
}
if (adcs_quat_normalize(target, &q_tgt) != ADCS_OK) {
    *error = (adcs_vec3_t){0.0, 0.0, 0.0};
    return ADCS_E_DEGENERATE;
}

q_conj = adcs_quat_conjugate(&q_est);
q_err = adcs_quat_multiply(&q_tgt, &q_conj);

if (q_err.w < 0.0) {
    q_err.w = -q_err.w;
    q_err.x = -q_err.x;
    q_err.y = -q_err.y;
    q_err.z = -q_err.z;
}

vec = (adcs_vec3_t){q_err.x, q_err.y, q_err.z};
s = adcs_vec3_norm(&vec);
if (s <= ADCS_EPS_QUAT) {
    *error = adcs_vec3_scale(&vec, 2.0);
    return ADCS_OK;
}
angle = 2.0 * atan2(s, q_err.w);
*error = adcs_vec3_scale(&vec, angle / s);
return ADCS_OK;
}

